'use strict';
(()=>{const key='guhuza.appearance',root=document.documentElement;let choice;try{choice=localStorage.getItem(key);}catch{}const system=window.matchMedia?.('(prefers-color-scheme: dark)');const apply=mode=>{root.dataset.theme=mode;root.style.colorScheme=mode;};apply(choice==='dark'||choice==='light'?choice:system?.matches?'dark':'light');system?.addEventListener?.('change',e=>{if(!choice){apply(e.matches?'dark':'light');paint();}});let toggle;
function paint(){if(!toggle)return;const dark=root.dataset.theme==='dark';toggle.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');toggle.title=dark?'Switch to light mode':'Switch to dark mode';toggle.setAttribute('aria-pressed',String(dark));toggle.innerHTML=dark?'<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/></svg>':'<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20.6 14A9 9 0 0 1 10 3.4 9 9 0 1 0 20.6 14Z"/></svg>';}
function start(){toggle=document.createElement('button');toggle.type='button';toggle.id='appearanceToggle';toggle.className='appearance-toggle';document.getElementById('accountMenu').before(toggle);toggle.onclick=()=>{choice=root.dataset.theme==='dark'?'light':'dark';apply(choice);try{localStorage.setItem(key,choice);}catch{}paint();};paint();}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();})();
